  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਰਹਿਮਤ ਸਿੰਘ ਦੀ ਇਮਾਨਦਾਰੀ ਦੀ ਘਟਨਾ ਨੂੰ ਆਪਣੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਬਿਆਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਪਾਠ ਤੋਂ ਪ੍ਰੇਰਨਾ ਲੈ ਕੇ ਤੁਸੀਂ ਆਪਣੇ ਜੀਵਨ ਵਿੱਚ ਕਿਹੜੇ ਬਦਲਾਅ ਲਿਆਉਣਾ ਚਾਹੋਗੇ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦਰਸਾਏ ਗਏ ਨੈਤਿਕ ਕਦਰਾਂ-ਕੀਮਤਾਂ ਦੀ ਸੂਚੀ ਬਣਾਓ ਅਤੇ ਹਰੇਕ ਦੀ ਸੰਖੇਪ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਗੁਰਮੀਤ ਸਿੰਘ ਦੀ ਸ਼ਖਸੀਅਤ ਵਿੱਚ ਰਹਿਮਤ ਸਿੰਘ ਨਾਲ ਮੁਲਾਕਾਤ ਤੋਂ ਪਹਿਲਾਂ ਅਤੇ ਬਾਅਦ ਵਿੱਚ ਕੀ ਅੰਤਰ ਆਇਆ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਰਹਿਮਤ ਸਿੰਘ ਨੇ ਗੁਰਮੀਤ ਸਿੰਘ ਨੂੰ ਇਨਾਮ ਲੈਣ ਤੋਂ ਇਨਕਾਰ ਕਰਦੇ ਹੋਏ ਕਿਹੜੀ ਦਲੀਲ ਦਿੱਤੀ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true);
INSERT INTO public.question_bank (id, institution_id, subject_id, topic_id, grade_level_id, class_group_id, question_text, question_type, options, correct_answer, marks, difficulty_level, tags, source, created_by, is_approved, parent_question_id, sub_question_count, sequence_order) VALUES
  ('0dad4afe-0af7-4397-abd6-50a9b8eb2db3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਸਟਰ ਗੁਰਮੀਤ ਸਿੰਘ ਚਿਹਰੇ ਉੱਤੇ ਵੱਡੀ ਸਾਰੀ ਮੁਸਕਾਨ ਲੈ ਕੇ ਜਮਾਤ ਵਿੱਚ ਦਾਖਲ ਹੁੰਦੇ। ਉਹਨਾਂ ਦੀਆਂ ਨਜ਼ਰਾਂ ਵਿੱਚਲਾ ਪਿਆਰ ਬੱਚਿਆਂ ਦੇ ਦਿਲ ਨੂੰ ਛੂਹ ਜਾਂਦਾ। ਜਮਾਤ ਦਾ ਮਾਹੌਲ ਖਿੜ ਜਾਂਦਾ। ਬੱਚਿਆਂ ਦੇ ਚਿਹਰਿਆਂ ਉੱਤੇ ਚਮਕ ਆ ਜਾਂਦੀ। ਮਾਪੇ ਵੀ ਉਸ ਵੱਲੋਂ ਬੱਚਿਆਂ ਦੀ ਪੜ੍ਹਾਈ ਲਈ ਕੀਤੀ ਜਾ ਰਹੀ ਮਿਹਨਤ ਦੀ ਸਿਫ਼ਤ ਕਰਦੇ ਨਾ ਥੱਕਦੇ। ਅਸਲ ਵਿੱਚ ਉਹ ਕੇਵਲ ਪੜ੍ਹਾਉਂਦੇ ਹੀ ਨਹੀਂ ਸਨ ਸਗੋਂ ਜ਼ਿੰਦਗੀ ਦੇ ਅਸਲ ਸਬਕ ਵੀ ਸਿਖਾਉਂਦੇ ਸਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8ad76595-ac76-4377-818b-f41c27522ac9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਗੁਰਮੀਤ ਸਿੰਘ ਸਿਰਫ਼ ਇੱਕ ਅਧਿਆਪਕ ਨਹੀਂ ਸੀ, ਘਰ ਵਿੱਚ ਇੱਕ ਸਪੁੱਤਰ, ਚੰਗਾ ਪਤੀ ਅਤੇ ਜ਼ਿੰਮੇਵਾਰ ਪਿਤਾ ਵੀ ਸੀ। ਉਸ ਦੀ ਉਮਰ ਹੁਣ ਪੰਤਾਲੀ ਟੱਪ ਗਈ ਸੀ ਅਤੇ ਘਰ ਅਤੇ ਸਕੂਲ ਦੀਆਂ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਨਾਲੋਂ-ਨਾਲ ਵੱਧ ਰਹੀਆਂ ਸਨ। ਆਲਮ ਇਹ ਸੀ ਕੰਮ ਦੇ ਇਸ ਵਧਦੇ ਬੋਝ ਨੇ ਉਸ ਨੂੰ ਚੀਜ਼ਾਂ ਭੁੱਲਣ ਦੀ ਆਦਤ ਪਾ ਦਿੱਤੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e2b91302-5bf5-4b51-a40c-e7e117f33e73', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਦੇ ਘਰ ਦੀ ਕੋਈ ਚੀਜ਼ ਗੁਆਚ ਜਾਂਦੀ ਤੇ ਕਦੇ ਸਕੂਲ ਦੀ ਕੋਈ ਜ਼ਰੂਰੀ ਫਾਈਲ। ਇਹ ਆਦਤ ਕਈ ਵਾਰੀ ਹਾਸੇ ਦਾ ਕਾਰਨ ਬਣਦੀ ਪਰ ਕਈ ਵਾਰੀ ਔਖੇ ਪਲ ਵੀ ਲਿਆਉਂਦੀ। ਇੱਕ-ਦੋ ਵਾਰ ਤਾਂ ਉਸ ਦਾ ਪਰਸ ਵੀ ਗੁਆਚ ਗਿਆ ਪਰ ਖੁਸ਼ਕਿਸਮਤੀ ਨਾਲ ਹਰ ਵਾਰ ਲੱਭ ਜਾਂਦਾ। ਇੰਝ ਜ਼ਿੰਦਗੀ ਦਾ ਸਮਾਂ ਚੰਗਾ ਲੰਘਦਾ ਜਾ ਰਿਹਾ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
