  ('47a34d18-784c-4d9c-b5f8-eae664833e71', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਗੁਰਮੀਤ ਨੇ ਫਟਾ-ਫਟ ਮੋਟਰਸਾਈਕਲ ਕੱਢਿਆ ਤੇ ਬੈਂਕ ਵੱਲ ਚੱਲ ਪਿਆ। ਉਸ ਨੇ ਜਲਦੀ ਨਾਲ ਬੈਂਕ ਕੋਲ ਲੱਗੀ ਆਟੋ ਟੈਲਰ ਮਸ਼ੀਨ (ਏ.ਟੀ.ਐਮ.) ਵਿੱਚੋਂ ਤੀਹ ਹਜ਼ਾਰ ਰੁਪਏ ਕਢਵਾਏ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8e210ba9-24a4-4bf8-a424-4244a20b9059', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਸਟਰ ਗੁਰਮੀਤ ਸਿੰਘ ਚਿਹਰੇ ਉੱਤੇ ਵੱਡੀ ਸਾਰੀ ਮੁਸਕਾਨ ਲੈ ਕੇ ਜਮਾਤ ਵਿੱਚ ਦਾਖਲ ਹੁੰਦੇ। ਉਹਨਾਂ ਦੀਆਂ ਨਜ਼ਰਾਂ ਵਿੱਚਲਾ ਪਿਆਰ ਬੱਚਿਆਂ ਦੇ ਦਿਲ ਨੂੰ ਛੂਹ ਜਾਂਦਾ। ਜਮਾਤ ਦਾ ਮਾਹੌਲ ਖਿੜ ਜਾਂਦਾ। ਬੱਚਿਆਂ ਦੇ ਚਿਹਰਿਆਂ ਉੱਤੇ ਚਮਕ ਆ ਜਾਂਦੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1e7200ef-b68b-49d3-aed7-fbbfd626e5c8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟਾਂ ਨਾਲ ਉਸ ਦਾ ਪਰਸ ਫੁੱਲ ਕੇ ਗੁਬਾਰੇ ਵਾਂਗ ਹੋ ਗਿਆ ਸੀ। ਉਸ ਨੇ ਅੱਖੇ-ਸੁੱਖੇ ਪਰਸ ਪੈਂਟ ਦੀ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਪਾਇਆ, ਕਿੱਕ ਮਾਰੀ ਤੇ ਘਰ ਵੱਲ ਚੱਲ ਪਿਆ। ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਜਾ ਕੇ ਜਦ ਉਸ ਨੇ ਆਦਤ ਅਨੁਸਾਰ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਮਾਰਿਆ ਤਾਂ ਜੇਬ੍ਹ ਖਾਲੀ ਸੀ। ਉਸ ਨੂੰ ਅਚੰਭਾ ਲੱਗਿਆ, ਵਿਸ਼ਵਾਸ ਨਾ ਹੋਇਆ। ਫਿਰ ਜੇਬ੍ਹ ਉੱਤੇ ਹੱਥ ਮਾਰਿਆ ਪਰ ਪਰਸ ਨਹੀਂ ਸੀ। ਉਸ ਨੇ ਫਟਾ-ਫਟ ਮੋਟਰਸਾਈਕਲ ਰੋਕੀ, ਕਾਹਲੀ ਨਾਲ ਸਾਰੀਆਂ ਜੇਬ੍ਹਾਂ ਵੇਖੀਆਂ ਪਰ ਪਰਸ ਨਾ ਮਿਲਿਆ। ਖਿਆਲ ਆਇਆ ਕਿ ਰਾਹ ਵਿੱਚ ਤਾਂ ਨਹੀਂ ਡਿੱਗ ਗਿਆ? ਅਣਗਿਣਤ ਖਿਆਲ ਮਨ ਵਿੱਚ ਘੁੰਮਣ ਲੱਗੇ, "ਇਹ ਤਾਂ ਮੇਰੀ ਮਿਹਨਤ ਦੀ ਕਮਾਈ ਸੀ। ਇਹ ਕਿਵੇਂ ਗੁਆਚ ਸਕਦੀ ਹੈ?" ਇੱਕ ਪਾਸੇ ਪਰਸ ਗੁਆਚਣ ਦਾ ਦੁੱਖ ਤੇ ਦੂਜੇ ਪਾਸੇ ਪੈਸਿਆਂ ਦੀ ਉਡੀਕ ਵਿੱਚ ਬੈਠੇ ਕਾਮੇ ਉਸ ਦੀ ਚਿੰਤਾ ਵਧਾ ਰਹੇ ਸਨ। ਉਸ ਨੇ ਤੁਰੰਤ ਮੋਟਰਸਾਈਕਲ ਘੁਮਾਇਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ab4587b3-266d-4086-b706-868d49b77dfa', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲ ਵਿੱਚ ਇੱਕ ਆਸ ਸੀ ਕਿ ਸ਼ਾਇਦ ਕਿਸੇ ਨੂੰ ਲੱਭ ਗਿਆ ਹੋਵੇ ਤੇ ਉਹ ਵਾਪਸ ਕਰ ਦੇਵੇਗਾ। ਪਰ ਦੂਜੇ ਹੀ ਪਲ ਇਹ ਸੋਚ ਬਦਲ ਜਾਂਦੀ ਕਿ ਅੱਜ ਦੇ ਜ਼ਮਾਨੇ ਵਿੱਚ ਜਿੱਥੇ ਲੋਕ ਹੱਥੋਂ ਮੋਬਾਈਲ ਤੇ ਘਰੋਂ ਕੀਮਤੀ ਸਮਾਨ ਖੋਹ ਕੇ ਭੱਜ ਜਾਂਦੇ ਨੇ, ਫਿਰ ਕਿਸੇ ਨੇ ਵਾਪਸ ਕਰਨਾ ਮੇਰਾ ਪਰਸ। ਨਾਲੇ ਪੰਜ-ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟ ਕਿਸੇ ਦਾ ਵੀ ਈਮਾਨ ਡੁਲਾ ਸਕਦੇ ਨੇ। ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਫੇਰਦਿਆਂ-ਫੇਰਦਿਆਂ ਜਦ ਉਹ ਬੈਂਕ ਤੋਂ ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਸੀ ਤਾਂ ਕਿਸੇ ਨੇ ਅਵਾਜ਼ ਮਾਰੀ, "ਸਰਦਾਰ ਜੀ, ਪਰਸ ਗੁਆਚ ਗਿਆ ਹੈ?" ਗੁਰਮੀਤ ਹੈਰਾਨ ਹੋ ਗਿਆ। ਉਹ ਸੋਚੀਂ ਪੈ ਗਿਆ। ਇਹ ਬਜ਼ੁਰਗ ਕੌਣ ਨੇ? ਇਹਨਾਂ ਨੂੰ ਕਿਵੇਂ ਪਤਾ ਲੱਗਿਆ ਮੇਰੇ ਪਰਸ ਗੁਆਚਣ ਦਾ? ਇਸ ਤੋਂ ਪਹਿਲਾਂ ਕਿ ਉਹ ਕੁਝ ਹੋਰ ਸੋਚਦਾ ਬਜ਼ੁਰਗ ਬੋਲਿਆ, "ਮੈਂ ਤਾਂ ਬਥੇਰੀਆਂ ਅਵਾਜ਼ਾਂ ਮਾਰੀਆਂ ਤੁਹਾਨੂੰ ਪਰ ਤੁਸੀਂ ਸੁਣੀਆਂ ਨਹੀਂ। ਤੁਸੀਂ ਤੇਜ਼ੀ ਵਿੱਚ ਸੀ। ਮੈਂ ਤੁਹਾਡੀ ਅਮਾਨਤ ਸੰਭਾਲ ਲਈ। ਮੈਨੂੰ ਪਤਾ ਸੀ ਤੁਸੀਂ ਵਾਪਸ ਆਓਗੇ।"$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d46a335c-50eb-4ace-9bf2-078918455bb1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਝ ਸਾਲ ਦੇ ਨੇੜੇ ਲੱਗਦੇ ਕਮਜ਼ੋਰ ਪਰ ਚਮਕਦੀਆਂ ਅੱਖਾਂ ਵਾਲੇ ਬਜ਼ੁਰਗ ਨੇ ਆਪਣੀ ਜੇਬ੍ਹ ਵਿੱਚੋਂ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਪਰਸ ਕੱਢਿਆ ਤੇ ਗੁਰਮੀਤ ਦੇ ਹਵਾਲੇ ਕਰ ਦਿੱਤਾ। ਪਰਸ ਵੇਖ ਕੇ ਉਸ ਦੀ ਜਾਨ ਵਿੱਚ ਜਾਨ ਆਈ। ਗੁਰਮੀਤ ਸਿੰਘ ਨੇ ਨਾ ਚਾਹੁੰਦਿਆਂ ਹੋਇਆਂ ਵੀ ਆਪਣਾ ਪਰਸ ਖੋਲ੍ਹ ਕੇ ਵੇਖਿਆ। ਪਰਸ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਸੀ। ਫਿਰ ਉਹ ਟਿਕਟਿਕੀ ਲਾ ਉਸ ਬਜ਼ੁਰਗ ਵੱਲ ਤੱਕਣ ਲੱਗਾ। ਖਸਤਾ ਹਾਲਤ ਦੇ ਰਿਕਸ਼ੇ ਤੇ ਸਧਾਰਨ ਜਿਹੇ ਕੱਪੜਿਆਂ ਵਿੱਚ ਬੈਠਾ ਉਹ ਬਜ਼ੁਰਗ ਉਸ ਨੂੰ ਅਸਧਾਰਨ ਜਾਪਿਆ। ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਉਸ ਪ੍ਰਤੀ ਅਥਾਹ ਸਤਿਕਾਰ ਪੈਦਾ ਹੋ ਗਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ee62e09b-afb6-479d-bb15-5269506e735e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟਾਂ ਨਾਲ ਉਸ ਦਾ ਪਰਸ ਫੁੱਲ ਕੇ ਗੁਬਾਰੇ ਵਾਂਗ ਹੋ ਗਿਆ ਸੀ। ਉਸ ਨੇ ਅੱਖੇ-ਸੁੱਖੇ ਪਰਸ ਪੈਂਟ ਦੀ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਪਾਇਆ, ਕਿੱਕ ਮਾਰੀ ਤੇ ਘਰ ਵੱਲ ਚੱਲ ਪਿਆ। ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਜਾ ਕੇ ਜਦ ਉਸ ਨੇ ਆਦਤ ਅਨੁਸਾਰ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਮਾਰਿਆ ਤਾਂ ਜੇਬ੍ਹ ਖਾਲੀ ਸੀ। ਉਸ ਨੂੰ ਅਚੰਭਾ ਲੱਗਿਆ, ਵਿਸ਼ਵਾਸ ਨਾ ਹੋਇਆ। ਫਿਰ ਜੇਬ੍ਹ ਉੱਤੇ ਹੱਥ ਮਾਰਿਆ ਪਰ ਪਰਸ ਨਹੀਂ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8de07555-13e5-4567-a343-22e4bcaf3c50', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਨੇ ਫਟਾ-ਫਟ ਮੋਟਰਸਾਈਕਲ ਰੋਕੀ, ਕਾਹਲੀ ਨਾਲ ਸਾਰੀਆਂ ਜੇਬ੍ਹਾਂ ਵੇਖੀਆਂ ਪਰ ਪਰਸ ਨਾ ਮਿਲਿਆ। ਖਿਆਲ ਆਇਆ ਕਿ ਰਾਹ ਵਿੱਚ ਤਾਂ ਨਹੀਂ ਡਿੱਗ ਗਿਆ? ਅਣਗਿਣਤ ਖਿਆਲ ਮਨ ਵਿੱਚ ਘੁੰਮਣ ਲੱਗੇ, "ਇਹ ਤਾਂ ਮੇਰੀ ਮਿਹਨਤ ਦੀ ਕਮਾਈ ਸੀ। ਇਹ ਕਿਵੇਂ ਗੁਆਚ ਸਕਦੀ ਹੈ?" ਇੱਕ ਪਾਸੇ ਪਰਸ ਗੁਆਚਣ ਦਾ ਦੁੱਖ ਤੇ ਦੂਜੇ ਪਾਸੇ ਪੈਸਿਆਂ ਦੀ ਉਡੀਕ ਵਿੱਚ ਬੈਠੇ ਕਾਮੇ ਉਸ ਦੀ ਚਿੰਤਾ ਵਧਾ ਰਹੇ ਸਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('70752f05-236a-456c-953a-d33acf8f0b97', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲ ਵਿੱਚ ਇੱਕ ਆਸ ਸੀ ਕਿ ਸ਼ਾਇਦ ਕਿਸੇ ਨੂੰ ਲੱਭ ਗਿਆ ਹੋਵੇ ਤੇ ਉਹ ਵਾਪਸ ਕਰ ਦੇਵੇਗਾ। ਪਰ ਦੂਜੇ ਹੀ ਪਲ ਇਹ ਸੋਚ ਬਦਲ ਜਾਂਦੀ ਕਿ ਅੱਜ ਦੇ ਜ਼ਮਾਨੇ ਵਿੱਚ ਜਿੱਥੇ ਲੋਕ ਹੱਥੋਂ ਮੋਬਾਈਲ ਤੇ ਘਰੋਂ ਕੀਮਤੀ ਸਮਾਨ ਖੋਹ ਕੇ ਭੱਜ ਜਾਂਦੇ ਨੇ, ਫਿਰ ਕਿਸੇ ਨੇ ਵਾਪਸ ਕਰਨਾ ਮੇਰਾ ਪਰਸ। ਨਾਲੇ ਪੰਜ-ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟ ਕਿਸੇ ਦਾ ਵੀ ਈਮਾਨ ਡੁਲਾ ਸਕਦੇ ਨੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('aa3c1b66-88e2-4362-aeae-c130cc3d29c4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਫੇਰਦਿਆਂ-ਫੇਰਦਿਆਂ ਜਦ ਉਹ ਬੈਂਕ ਤੋਂ ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਸੀ ਤਾਂ ਕਿਸੇ ਨੇ ਅਵਾਜ਼ ਮਾਰੀ, "ਸਰਦਾਰ ਜੀ, ਪਰਸ ਗੁਆਚ ਗਿਆ ਹੈ?" ਗੁਰਮੀਤ ਹੈਰਾਨ ਹੋ ਗਿਆ। ਉਹ ਸੋਚੀਂ ਪੈ ਗਿਆ। ਇਹ ਬਜ਼ੁਰਗ ਕੌਣ ਨੇ? ਇਹਨਾਂ ਨੂੰ ਕਿਵੇਂ ਪਤਾ ਲੱਗਿਆ ਮੇਰੇ ਪਰਸ ਗੁਆਚਣ ਦਾ? ਇਸ ਤੋਂ ਪਹਿਲਾਂ ਕਿ ਉਹ ਕੁਝ ਹੋਰ ਸੋਚਦਾ ਬਜ਼ੁਰਗ ਬੋਲਿਆ, "ਮੈਂ ਤਾਂ ਬਥੇਰੀਆਂ ਅਵਾਜ਼ਾਂ ਮਾਰੀਆਂ ਤੁਹਾਨੂੰ ਪਰ ਤੁਸੀਂ ਸੁਣੀਆਂ ਨਹੀਂ। ਤੁਸੀਂ ਤੇਜ਼ੀ ਵਿੱਚ ਸੀ। ਮੈਂ ਤੁਹਾਡੀ ਅਮਾਨਤ ਸੰਭਾਲ ਲਈ। ਮੈਨੂੰ ਪਤਾ ਸੀ ਤੁਸੀਂ ਵਾਪਸ ਆਓਗੇ।"$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('964ac6c4-15ec-4297-9fcc-4d24560d36cc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਝ ਸਾਲ ਦੇ ਨੇੜੇ ਲੱਗਦੇ ਕਮਜ਼ੋਰ ਪਰ ਚਮਕਦੀਆਂ ਅੱਖਾਂ ਵਾਲੇ ਬਜ਼ੁਰਗ ਨੇ ਆਪਣੀ ਜੇਬ੍ਹ ਵਿੱਚੋਂ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਪਰਸ ਕੱਢਿਆ ਤੇ ਗੁਰਮੀਤ ਦੇ ਹਵਾਲੇ ਕਰ ਦਿੱਤਾ। ਪਰਸ ਵੇਖ ਕੇ ਉਸ ਦੀ ਜਾਨ ਵਿੱਚ ਜਾਨ ਆਈ। ਗੁਰਮੀਤ ਸਿੰਘ ਨੇ ਨਾ ਚਾਹੁੰਦਿਆਂ ਹੋਇਆਂ ਵੀ ਆਪਣਾ ਪਰਸ ਖੋਲ੍ਹ ਕੇ ਵੇਖਿਆ। ਪਰਸ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0222a3d3-3c99-4512-9ff0-e953a285c68d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਿਰ ਉਹ ਟਿਕਟਿਕੀ ਲਾ ਉਸ ਬਜ਼ੁਰਗ ਵੱਲ ਤੱਕਣ ਲੱਗਾ। ਖਸਤਾ ਹਾਲਤ ਦੇ ਰਿਕਸ਼ੇ ਤੇ ਸਧਾਰਨ ਜਿਹੇ ਕੱਪੜਿਆਂ ਵਿੱਚ ਬੈਠਾ ਉਹ ਬਜ਼ੁਰਗ ਉਸ ਨੂੰ ਅਸਧਾਰਨ ਜਾਪਿਆ। ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਉਸ ਪ੍ਰਤੀ ਅਥਾਹ ਸਤਿਕਾਰ ਪੈਦਾ ਹੋ ਗਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ecf43798-1c77-4794-add7-4a8603a4ded3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟਾਂ ਨਾਲ ਉਸ ਦਾ ਪਰਸ ਫੁੱਲ ਕੇ ਗੁਬਾਰੇ ਵਾਂਗ ਹੋ ਗਿਆ ਸੀ। ਉਸ ਨੇ ਅੱਖੇ-ਸੁੱਖੇ ਪਰਸ ਪੈਂਟ ਦੀ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਪਾਇਆ, ਕਿੱਕ ਮਾਰੀ ਤੇ ਘਰ ਵੱਲ ਚੱਲ ਪਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e5eb0283-c2a3-49da-92fb-941c618b0501', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਜਾ ਕੇ ਜਦ ਉਸ ਨੇ ਆਦਤ ਅਨੁਸਾਰ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਮਾਰਿਆ ਤਾਂ ਜੇਬ੍ਹ ਖਾਲੀ ਸੀ। ਉਸ ਨੂੰ ਅਚੰਭਾ ਲੱਗਿਆ, ਵਿਸ਼ਵਾਸ ਨਾ ਹੋਇਆ। ਫਿਰ ਜੇਬ੍ਹ ਉੱਤੇ ਹੱਥ ਮਾਰਿਆ ਪਰ ਪਰਸ ਨਹੀਂ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
