  ('5f439713-6b7f-44fb-8ccb-29c96651ded5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਤੋਂ ਪਹਿਲਾਂ ਕਿ ਉਹ ਕੁਝ ਹੋਰ ਸੋਚਦਾ ਬਜ਼ੁਰਗ ਬੋਲਿਆ, "ਮੈਂ ਤਾਂ ਬਥੇਰੀਆਂ ਅਵਾਜ਼ਾਂ ਮਾਰੀਆਂ ਤੁਹਾਨੂੰ ਪਰ ਤੁਸੀਂ ਸੁਣੀਆਂ ਨਹੀਂ। ਤੁਸੀਂ ਤੇਜ਼ੀ ਵਿੱਚ ਸੀ। ਮੈਂ ਤੁਹਾਡੀ ਅਮਾਨਤ ਸੰਭਾਲ ਲਈ। ਮੈਨੂੰ ਪਤਾ ਸੀ ਤੁਸੀਂ ਵਾਪਸ ਆਓਗੇ।" ਕੁਝ ਸਾਲ ਦੇ ਨੇੜੇ ਲੱਗਦੇ ਕਮਜ਼ੋਰ ਪਰ ਚਮਕਦੀਆਂ ਅੱਖਾਂ ਵਾਲੇ ਬਜ਼ੁਰਗ ਨੇ ਆਪਣੀ ਜੇਬ੍ਹ ਵਿੱਚੋਂ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਪਰਸ ਕੱਢਿਆ ਤੇ ਗੁਰਮੀਤ ਦੇ ਹਵਾਲੇ ਕਰ ਦਿੱਤਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e92023a3-b874-44e2-a40c-985f81eb7e31', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰਸ ਵੇਖ ਕੇ ਉਸ ਦੀ ਜਾਨ ਵਿੱਚ ਜਾਨ ਆਈ। ਗੁਰਮੀਤ ਸਿੰਘ ਨੇ ਨਾ ਚਾਹੁੰਦਿਆਂ ਹੋਇਆਂ ਵੀ ਆਪਣਾ ਪਰਸ ਖੋਲ੍ਹ ਕੇ ਵੇਖਿਆ। ਪਰਸ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਸੀ। ਫਿਰ ਉਹ ਟਿਕਟਿਕੀ ਲਾ ਉਸ ਬਜ਼ੁਰਗ ਵੱਲ ਤੱਕਣ ਲੱਗਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2447b10d-2cf4-4cd9-afe8-9405bbbf7fb6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਖਸਤਾ ਹਾਲਤ ਦੇ ਰਿਕਸ਼ੇ ਤੇ ਸਧਾਰਨ ਜਿਹੇ ਕੱਪੜਿਆਂ ਵਿੱਚ ਬੈਠਾ ਉਹ ਬਜ਼ੁਰਗ ਉਸ ਨੂੰ ਅਸਧਾਰਨ ਜਾਪਿਆ। ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਉਸ ਪ੍ਰਤੀ ਅਥਾਹ ਸਤਿਕਾਰ ਪੈਦਾ ਹੋ ਗਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d431604a-4020-4909-b682-bafa9fcf908b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟਾਂ ਨਾਲ ਉਸ ਦਾ ਪਰਸ ਫੁੱਲ ਕੇ ਗੁਬਾਰੇ ਵਾਂਗ ਹੋ ਗਿਆ ਸੀ। ਉਸ ਨੇ ਅੱਖੇ-ਸੁੱਖੇ ਪਰਸ ਪੈਂਟ ਦੀ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਪਾਇਆ, ਕਿੱਕ ਮਾਰੀ ਤੇ ਘਰ ਵੱਲ ਚੱਲ ਪਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
