  ('008902a4-a398-4571-9a43-61dd2f0ec009', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰਸ ਵੇਖ ਕੇ ਉਸ ਦੀ ਜਾਨ ਵਿੱਚ ਜਾਨ ਆਈ। ਗੁਰਮੀਤ ਸਿੰਘ ਨੇ ਨਾ ਚਾਹੁੰਦਿਆਂ ਹੋਇਆਂ ਵੀ ਆਪਣਾ ਪਰਸ ਖੋਲ੍ਹ ਕੇ ਵੇਖਿਆ। ਪਰਸ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('38137b27-6e99-44de-9ecb-bac37c8341c9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਿਰ ਉਹ ਟਿਕਟਿਕੀ ਲਾ ਉਸ ਬਜ਼ੁਰਗ ਵੱਲ ਤੱਕਣ ਲੱਗਾ। ਖਸਤਾ ਹਾਲਤ ਦੇ ਰਿਕਸ਼ੇ ਤੇ ਸਧਾਰਨ ਜਿਹੇ ਕੱਪੜਿਆਂ ਵਿੱਚ ਬੈਠਾ ਉਹ ਬਜ਼ੁਰਗ ਉਸ ਨੂੰ ਅਸਧਾਰਨ ਜਾਪਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e27cb3d2-5d65-438d-bd48-844d9b155f97', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਉਸ ਪ੍ਰਤੀ ਅਥਾਹ ਸਤਿਕਾਰ ਪੈਦਾ ਹੋ ਗਿਆ। ਉਹ ਨਵੇਂ-ਨਕੋਰ-ਬਿਲਕੁਲ ਨਵੇਂ (crisp new notes), ਅਥਾਹ-ਬੇਅੰਤ, ਬਹੁਤ ਵੱਧ (immense/limitless), ਖਸਤਾ ਹਾਲਤ - ਬਹੁਤ ਮਾੜੀ ਹਾਲਤ (poor condition)Í$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('cf42f668-11df-418c-8700-45b1e6827041', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟਾਂ ਨਾਲ ਉਸ ਦਾ ਪਰਸ ਫੁੱਲ ਕੇ ਗੁਬਾਰੇ ਵਾਂਗ ਹੋ ਗਿਆ ਸੀ। ਉਸ ਨੇ ਅੱਖੇ-ਸੁੱਖੇ ਪਰਸ ਪੈਂਟ ਦੀ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਪਾਇਆ, ਕਿੱਕ ਮਾਰੀ ਤੇ ਘਰ ਵੱਲ ਚੱਲ ਪਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('74ee7715-aa6b-45b9-831c-6a7411b8fea5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਜਾ ਕੇ ਜਦ ਉਸ ਨੇ ਆਦਤ ਅਨੁਸਾਰ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਮਾਰਿਆ ਤਾਂ ਜੇਬ੍ਹ ਖਾਲੀ ਸੀ। ਉਸ ਨੂੰ ਅਚੰਭਾ ਲੱਗਿਆ, ਵਿਸ਼ਵਾਸ ਨਾ ਹੋਇਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('5d3f177b-19e1-47bf-affa-c463a904fd29', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੱਕ ਪਾਸੇ ਪਰਸ ਗੁਆਚਣ ਦਾ ਦੁੱਖ ਤੇ ਦੂਜੇ ਪਾਸੇ ਪੈਸਿਆਂ ਦੀ ਉਡੀਕ ਵਿੱਚ ਬੈਠੇ ਕਾਮੇ ਉਸ ਦੀ ਚਿੰਤਾ ਵਧਾ ਰਹੇ ਸਨ। ਉਸ ਨੇ ਤੁਰੰਤ ਮੋਟਰਸਾਈਕਲ ਘੁਮਾਇਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('5d7ec835-0c50-4315-a7e3-1cbf35f08c38', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬਜ਼ੁਰਗ ਬੋਲਿਆ, "ਮੈਂ ਤਾਂ ਬਥੇਰੀਆਂ ਅਵਾਜ਼ਾਂ ਮਾਰੀਆਂ ਤੁਹਾਨੂੰ ਪਰ ਤੁਸੀਂ ਸੁਣੀਆਂ ਨਹੀਂ। ਤੁਸੀਂ ਤੇਜ਼ੀ ਵਿੱਚ ਸੀ। ਮੈਂ ਤੁਹਾਡੀ ਅਮਾਨਤ ਸੰਭਾਲ ਲਈ। ਮੈਨੂੰ ਪਤਾ ਸੀ ਤੁਸੀਂ ਵਾਪਸ ਆਓਗੇ।"$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('0f1e3d10-56b0-4a1a-b0ee-1b332014ac27', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸੋਚ ਰਿਹਾ ਸੀ ਕਿ ਹਰ ਰੋਜ਼ ਤਿੰਨ ਤੋਂ ਚਾਰ ਸੌ ਰੁਪਏ ਕਮਾਉਣ ਵਾਲੇ ਦੇ ਮਨ ਵਿੱਚ ਇਸ ਪਰਸ ਨੂੰ ਰੱਖਣ ਦਾ ਲਾਲਚ ਕਿਉਂ ਨਾ ਆਇਆ? ਇਹਨਾਂ ਪੈਸਿਆਂ ਨਾਲ ਉਸ ਦਾ ਸਾਲ ਭਰ ਦਾ ਖਰਚਾ ਬਣੇ ਲੱਗ ਜਾਣਾ ਸੀ। ਉਸ ਅੰਦਰ ਐਸਾ ਕੀ ਹੈ ਜੋ ਆਮ ਲੋਕਾਂ ਵਿੱਚ ਨਹੀਂ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9dd009d9-79a1-4890-9507-099d0e1e7d9c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਨੇ ਪੰਜ-ਪੰਜ ਸੌ ਦੇ ਦੋ ਨੋਟ ਰਿਕਸ਼ੇ ਵਾਲੇ ਵੱਲ ਵਧਾ ਕੇ ਬੜੇ ਸਤਿਕਾਰ ਨਾਲ ਕਿਹਾ, ÒÒਤੁਹਾਡਾ ਇਨਾਮ ਬਜ਼ੁਰਗੋ।ÓÓ ÒÒਤੁਹਾਡਾ ਦਿਲੋਂ ਸ਼ੁਕਰਾਨਾ।ÓÓ ਬਜ਼ੁਰਗ ਰਿਕਸ਼ੇ ਵਾਲੇ ਨੇ ਥੋੜ੍ਹਾ ਮੁਸਕੁਰਾ ਕੇ ਬੜੇ ਅਦਬ ਨਾਲ ਕਿਹਾ, ÒÒਨਹੀਂ ਸਰਦਾਰ ਸਾਹਿਬ, ਇਹ ਪੈਸੇ ਮੈਂ ਨਹੀਂ ਲੈਣੇ। ਇਹਨਾਂ ਉੱਤੇ ਮੇਰਾ ਕੋਈ ਹੱਕ ਨਹੀਂ। ਇਹ ਤੁਹਾਡੀ ਦਸਾਂ-ਨਹੁੰਆਂ ਦੀ ਕਿਰਤ ਹੈ।ÓÓ$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b2343e46-52fa-4fc0-a2ac-fb6531c4b6e1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਗੁਰਮੀਤ ਸਿੰਘ ਮੁਸਕੁਰਾ ਕੇ ਕਹਿਣ ਲੱਗਾ, ÒÒਇਹ ਤੁਹਾਡੀ ਇਮਾਨਦਾਰੀ ਦਾ ਇਨਾਮ ਹੈ ਬਾਬਾ ਜੀ।ÓÓ ÒÒਨਹੀਂ ਸਰਦਾਰ ਸਾਹਿਬ, ਮੈਂ ਕਿਸੇ ਦੀ ਕਿਰਤ-ਕਮਾਈ ਨਹੀਂ ਲੈ ਸਕਦਾ। ਤੁਹਾਡਾ ਪਰਸ ਵਾਪਸ ਕਰਕੇ ਤਾਂ ਮੈਂ ਆਪਣਾ ਫਰਜ਼ ਨਿਭਾਇਆ ਹੈ।ÓÓ$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fc6753fa-1758-4dfd-8596-8d59b344ce36', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਗੱਲ ਸੁਣਦਿਆਂ ਹੀ ਗੁਰਮੀਤ ਸਿੰਘ ਦੀਆਂ ਅੱਖਾਂ ਨਮ ਹੋ ਗਈਆਂ। ਘੋਰ ਗਰੀਬੀ ਦਾ ਸਾਹਮਣਾ ਕਰ ਰਿਹਾ ਇਹ ਰਿਕਸ਼ਾ ਚਾਲਕ ਉਸ ਨੂੰ ਕਿਸੇ ਦਾਤੇ ਤੋਂ ਘੱਟ ਨਹੀਂ ਲੱਗ ਰਿਹਾ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ea0e0d79-d458-42b5-b4e7-e42ab7fe09eb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਗੁਰਮੀਤ ਨੂੰ ਸੋਚਾਂ ਵਿੱਚ ਗੁਆਚਿਆ ਵੇਖ ਰਿਕਸ਼ਾ ਵਾਲਾ ਬੋਲਿਆ, ÒÒਕੀ ਹੋ ਗਿਆ ਸਰਦਾਰ ਜੀ? ਕੀ ਸੋਚਣ ਲੱਗ ਪਏ?ÓÓ ÒÒਕੁਝ ਨਹੀਂ... ਕੁਝ ਨਹੀਂ, ਬੱਸ ਐਵੇਂ ਹੀ। ਤੁਹਾਡਾ ਨਾਂ ਕੀ ਹੈ ਬਾਬਾ ਜੀ? ਤੁਸੀਂ ਕਿੱਥੇ ਰਹਿੰਦੇ ਹੋ?ÓÓ ਗੁਰਮੀਤ ਸਿੰਘ ਬੋਲਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8030cb37-759b-415f-8fe5-12e3b5becaf7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ÒÒਰਹਿਮਤ ਸਿੰਘ ਐ ਮੇਰਾ ਨਾਂ ਸਰਦਾਰ ਸਾਹਿਬ,ÓÓ ਬਜ਼ੁਰਗ ਨੇ ਨਿਮਰਤਾ ਨਾਲ ਜਵਾਬ ਦਿੱਤਾ। ਉਸ ਦਾ ਨਾਂ ਸੁਣ ਕੇ ਗੁਰਮੀਤ ਨੂੰ ਇੰਝ ਲੱਗਿਆ ਕਿ ਮਹੀਨੇ ਵਿੱਚ ਦੋ-ਤਿੰਨ ਹਜ਼ਾਰ ਰੁਪਏ ਕਮਾਉਣ ਵਾਲੇ ਰਹਿਮਤ ਸਿੰਘ ਉੱਤੇ ਸੱਚ-ਮੁੱਚ ਖੁਦਾ ਦੀ ਰਹਿਮਤ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('70bceb9e-1337-413c-b932-c48af45ac5ce', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਰਹਿਮਤ ਸਿੰਘ ਦੀ ਖੁਦਦਾਰੀ, ਇਮਾਨਦਾਰੀ ਅਤੇ ਚੜ੍ਹਦੀ ਕਲਾ ਵਿੱਚ ਰਹਿਣ ਦਾ ਸਰੂਰ ਗੁਰਮੀਤ ਸਿੰਘ ਦੇ ਚੇਤੇ ਵਿੱਚ ਵੱਸ ਗਿਆ। ਉਸ ਦਿਨ ਤੋਂ ਗੁਰਮੀਤ ਸਿੰਘ ਦੀ ਸੋਚ ਬਦਲ ਗਈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ff03e013-93e7-4548-8bc9-7d9b39a93de0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਜੋਕੀ ਦੁਨੀਆ ਵਿੱਚ ਵੱਧ ਰਹੇ ਲਾਲਚ ਅਤੇ ਚੋਰੀ-ਠੱਗੀ ਦੀਆਂ ਘਟਨਾਵਾਂ ਵਿਚਕਾਰ ਵੀ ਰਹਿਮਤ ਸਿੰਘ ਵਰਗਾ ਬੰਦਾ ਬਾਕੀ ਹੈ। ਅੱਜ ਵੀ ਜਦੋਂ ਕਦੇ ਗੁਰਮੀਤ ਸਿੰਘ ਦਾ ਕੋਈ ਛੋਟਾ-ਮੋਟਾ ਨੁਕਸਾਨ ਹੋ ਜਾਂਦਾ ਜਾਂ ਕਿਸੇ ਦੀ ਕੀਤੀ ਚਲਾਕੀ ਜਾਂ ਠੱਗੀ ਸਾਹਮਣੇ ਆਉਂਦੀ ਤਾਂ ਉਹ ਅੱਖਾਂ ਬੰਦ ਕਰਕੇ ਰਹਿਮਤ ਸਿੰਘ ਨੂੰ ਯਾਦ ਕਰ ਲੈਂਦਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2342fec4-453e-42fe-b39a-22f7ba8a0f56', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹ ਸੋਚਦਾ ਹੈ ਕਿ ਸੱਚ, ਇਮਾਨਦਾਰੀ ਅਤੇ ਖੁਦਦਾਰੀ ਕਿਸੇ ਵੱਡੇ ਰੁਤਬੇ ਜਾਂ ਮਣਾਂ-ਮੂੰਹੀਂ ਦੌਲਤ ਨਾਲ ਨਹੀਂ, ਸਗੋਂ ਚੰਗੇ ਸੰਸਕਾਰ, ਸਬਰ ਅਤੇ ਰੱਬੀ ਰਹਿਮਤ ਨਾਲ ਹੀ ਮਿਲਦੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5dbf6381-5f6c-40bf-a983-6954b461fa29', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲਾਲਚ - ਲੋਭ, ਫਰਜ਼ ਨਿਭਾਉਣਾ - ਆਪਣੀ ਜ਼ਿੰਮੇਵਾਰੀ ਪੂਰੀ ਕਰਨਾ, ਨਿਮਰਤਾ - ਹਲੀਮੀ, ਖੁਦਦਾਰੀ - ਸਵੈ-ਸਨਮਾਨ, ਚੜ੍ਹਦੀ ਕਲਾ - ਉੱਚੇ ਮਨੋਬਲ ਵਿੱਚ ਰਹਿਣਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('46d11f1e-7de2-443d-826e-bf5d4211c1d5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੂਜਿਆਂ ਪ੍ਰਤੀ ਇਮਾਨਦਾਰੀ ਦਿਖਾਉਣ ਦੀ ਭਾਵਨਾ ਦਾ ਵਿਕਾਸ। ਸੰਤੁਸ਼ਟੀ ਨਾਲ ਜੀਵਨ ਜਿਊਣ ਦੀ ਪ੍ਰੇਰਨਾ ਪੈਦਾ ਹੋਈ। ਸਿੱਖਣ ਨਤੀਜੇ (Learning Outcomes)$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8f285bee-a0d2-4068-9734-0a2d4b65d1d3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਸਟਰ ਗੁਰਮੀਤ ਸਿੰਘ ਚਿਹਰੇ ਉੱਤੇ ਵੱਡੀ ਸਾਰੀ ਮੁਸਕਾਨ ਲੈ ਕੇ ਜਮਾਤ ਵਿੱਚ ਦਾਖਲ ਹੁੰਦੇ। ਉਹਨਾਂ ਦੀਆਂ ਨਜ਼ਰਾਂ ਵਿੱਚਲਾ ਪਿਆਰ ਬੱਚਿਆਂ ਦੇ ਦਿਲ ਨੂੰ ਛੂਹ ਜਾਂਦਾ। ਜਮਾਤ ਦਾ ਮਾਹੌਲ ਖਿੜ ਜਾਂਦਾ। ਬੱਚਿਆਂ ਦੇ ਚਿਹਰਿਆਂ ਉੱਤੇ ਚਮਕ ਆ ਜਾਂਦੀ। ਮਾਪੇ ਵੀ ਉਸ ਵੱਲੋਂ ਬੱਚਿਆਂ ਦੀ ਪੜ੍ਹਾਈ ਲਈ ਕੀਤੀ ਜਾ ਰਹੀ ਮਿਹਨਤ ਦੀ ਸਿਫ਼ਤ ਕਰਦੇ ਨਾ ਥੱਕਦੇ। ਅਸਲ ਵਿੱਚ ਉਹ ਕੇਵਲ ਪੜ੍ਹਾਉਂਦੇ ਹੀ ਨਹੀਂ ਸਨ ਸਗੋਂ ਜ਼ਿੰਦਗੀ ਦੇ ਅਸਲ ਸਬਕ ਵੀ ਸਿਖਾਉਂਦੇ ਸਨ। ਗੁਰਮੀਤ ਸਿੰਘ ਸਿਰਫ਼ ਇੱਕ ਅਧਿਆਪਕ ਨਹੀਂ ਸੀ, ਘਰ ਵਿੱਚ ਇੱਕ ਸਪੁੱਤਰ, ਚੰਗਾ ਪਤੀ ਅਤੇ ਜ਼ਿੰਮੇਵਾਰ ਪਿਤਾ ਵੀ ਸੀ। ਉਸ ਦੀ ਉਮਰ ਹੁਣ ਪੰਤਾਲੀ ਟੱਪ ਗਈ ਸੀ ਅਤੇ ਘਰ ਅਤੇ ਸਕੂਲ ਦੀਆਂ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਨਾਲੋਂ-ਨਾਲ ਵੱਧ ਰਹੀਆਂ ਸਨ। ਆਲਮ ਇਹ ਸੀ ਕੰਮ ਦੇ ਇਸ ਵਧਦੇ ਬੋਝ ਨੇ ਉਸ ਨੂੰ ਚੀਜ਼ਾਂ ਭੁੱਲਣ ਦੀ ਆਦਤ ਪਾ ਦਿੱਤੀ। ਕਦੇ ਘਰ ਦੀ ਕੋਈ ਚੀਜ਼ ਗੁਆਚ ਜਾਂਦੀ ਤੇ ਕਦੇ ਸਕੂਲ ਦੀ ਕੋਈ ਜ਼ਰੂਰੀ ਫਾਈਲ। ਇਹ ਆਦਤ ਕਈ ਵਾਰੀ ਹਾਸੇ ਦਾ ਕਾਰਨ ਬਣਦੀ ਪਰ ਕਈ ਵਾਰੀ ਔਖੇ ਪਲ ਵੀ ਲਿਆਉਂਦੀ। ਇੱਕ-ਦੋ ਵਾਰ ਤਾਂ ਉਸ ਦਾ ਪਰਸ ਵੀ ਗੁਆਚ ਗਿਆ ਪਰ ਖੁਸ਼ਕਿਸਮਤੀ ਨਾਲ ਹਰ ਵਾਰ ਲੱਭ ਜਾਂਦਾ। ਇੰਝ ਜ਼ਿੰਦਗੀ ਦਾ ਸਮਾਂ ਚੰਗਾ ਲੰਘਦਾ ਜਾ ਰਿਹਾ ਸੀ। ਗੁਰਮੀਤ ਸਿੰਘ ਦੇ ਘਰ ਮਿਸਤਰੀ ਲੱਗੇ ਹੋਏ ਸਨ। ਬਜ਼ੁਰਗਾਂ ਲਈ ਨਵਾਂ ਬਾਥਰੂਮ ਅਤੇ ਗੱਡੀਆਂ ਖੜ੍ਹੀਆਂ ਕਰਨ ਲਈ ਸ਼ੈੱਡ ਬਣਾਇਆ ਜਾ ਰਿਹਾ ਸੀ। ਅੱਜ ਵਧੇਰੇ ਕੰਮ ਹੋਣ ਕਰਕੇ ਉਸ ਨੇ ਸਕੂਲ ਤੋਂ ਛੁੱਟੀ ਲੈ ਲਈ। ਦੁਪਹਿਰ ਅਜੇ ਪੂਰੀ ਤਰ੍ਹਾਂ ਬੀਤੀ ਨਹੀਂ ਸੀ ਕਿ ਕੰਮਾਂ ਉਜਰਤ ਦੀ ਮੰਗ ਕਰਨ ਲੱਗੇ। ਗੁਰਮੀਤ ਸਿੰਘ ਸੋਚਣ ਲੱਗਾ, ਇਹਨਾਂ ਜੋ ਕਮਾਉਣਾ ਹੈ, ਉਹੋ ਹੀ ਖਾਣਾ ਹੈ। ਗੁਰਮੀਤ ਨੇ ਫਟਾ-ਫਟ ਮੋਟਰਸਾਈਕਲ ਕੱਢਿਆ ਤੇ ਬੈਂਕ ਵੱਲ ਚੱਲ ਪਿਆ। ਉਸ ਨੇ ਜਲਦੀ ਨਾਲ ਬੈਂਕ ਕੋਲ ਲੱਗੀ ਆਟੋ ਟੈਲਰ ਮਸ਼ੀਨ (ਏ.ਟੀ.ਐਮ.) ਵਿੱਚੋਂ ਤੀਹ ਹਜ਼ਾਰ ਰੁਪਏ ਕਢਵਾਏ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 34, NULL),
  ('4dc19cac-b823-4260-86bd-6f0d66ed2b74', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟਾਂ ਨਾਲ ਉਸ ਦਾ ਪਰਸ ਫੁੱਲ ਕੇ ਗੁਬਾਰੇ ਵਾਂਗ ਹੋ ਗਿਆ ਸੀ। ਉਸ ਨੇ ਅੱਖੇ-ਸੁੱਖੇ ਪਰਸ ਪੈਂਟ ਦੀ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਪਾਇਆ, ਕਿੱਕ ਮਾਰੀ ਤੇ ਘਰ ਵੱਲ ਚੱਲ ਪਿਆ। ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਜਾ ਕੇ ਜਦ ਉਸ ਨੇ ਆਦਤ ਅਨੁਸਾਰ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਮਾਰਿਆ ਤਾਂ ਜੇਬ੍ਹ ਖਾਲੀ ਸੀ। ਉਸ ਨੂੰ ਅਚੰਭਾ ਲੱਗਿਆ, ਵਿਸ਼ਵਾਸ ਨਾ ਹੋਇਆ। ਫਿਰ ਜੇਬ੍ਹ ਉੱਤੇ ਹੱਥ ਮਾਰਿਆ ਪਰ ਪਰਸ ਨਹੀਂ ਸੀ। ਉਸ ਨੇ ਫਟਾ-ਫਟ ਮੋਟਰਸਾਈਕਲ ਰੋਕੀ, ਕਾਹਲੀ ਨਾਲ ਸਾਰੀਆਂ ਜੇਬ੍ਹਾਂ ਵੇਖੀਆਂ ਪਰ ਪਰਸ ਨਾ ਮਿਲਿਆ। ਖਿਆਲ ਆਇਆ ਕਿ ਰਾਹ ਵਿੱਚ ਤਾਂ ਨਹੀਂ ਡਿੱਗ ਗਿਆ? ਅਣਗਿਣਤ ਖਿਆਲ ਮਨ ਵਿੱਚ ਘੁੰਮਣ ਲੱਗੇ, "ਇਹ ਤਾਂ ਮੇਰੀ ਮਿਹਨਤ ਦੀ ਕਮਾਈ ਸੀ। ਇਹ ਕਿਵੇਂ ਗੁਆਚ ਸਕਦੀ ਹੈ?" ਇੱਕ ਪਾਸੇ ਪਰਸ ਗੁਆਚਣ ਦਾ ਦੁੱਖ ਤੇ ਦੂਜੇ ਪਾਸੇ ਪੈਸਿਆਂ ਦੀ ਉਡੀਕ ਵਿੱਚ ਬੈਠੇ ਕਾਮੇ ਉਸ ਦੀ ਚਿੰਤਾ ਵਧਾ ਰਹੇ ਸਨ। ਉਸ ਨੇ ਤੁਰੰਤ ਮੋਟਰਸਾਈਕਲ ਘੁਮਾਇਆ। ਦਿਲ ਵਿੱਚ ਇੱਕ ਆਸ ਸੀ ਕਿ ਸ਼ਾਇਦ ਕਿਸੇ ਨੂੰ ਲੱਭ ਗਿਆ ਹੋਵੇ ਤੇ ਉਹ ਵਾਪਸ ਕਰ ਦੇਵੇਗਾ। ਪਰ ਦੂਜੇ ਹੀ ਪਲ ਇਹ ਸੋਚ ਬਦਲ ਜਾਂਦੀ ਕਿ ਅੱਜ ਦੇ ਜ਼ਮਾਨੇ ਵਿੱਚ ਜਿੱਥੇ ਲੋਕ ਹੱਥੋਂ ਮੋਬਾਈਲ ਤੇ ਘਰੋਂ ਕੀਮਤੀ ਸਮਾਨ ਖੋਹ ਕੇ ਭੱਜ ਜਾਂਦੇ ਨੇ, ਫਿਰ ਕਿਸੇ ਨੇ ਵਾਪਸ ਕਰਨਾ ਮੇਰਾ ਪਰਸ। ਨਾਲੇ ਪੰਜ-ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟ ਕਿਸੇ ਦਾ ਵੀ ਈਮਾਨ ਡੁਲਾ ਸਕਦੇ ਨੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f5ae9b1b-f5b5-4d08-8976-f4cacf920d21', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਫੇਰਦਿਆਂ-ਫੇਰਦਿਆਂ ਜਦ ਉਹ ਬੈਂਕ ਤੋਂ ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਸੀ ਤਾਂ ਕਿਸੇ ਨੇ ਅਵਾਜ਼ ਮਾਰੀ, "ਸਰਦਾਰ ਜੀ, ਪਰਸ ਗੁਆਚ ਗਿਆ ਹੈ?" ਗੁਰਮੀਤ ਹੈਰਾਨ ਹੋ ਗਿਆ। ਉਹ ਸੋਚੀਂ ਪੈ ਗਿਆ। ਇਹ ਬਜ਼ੁਰਗ ਕੌਣ ਨੇ? ਇਹਨਾਂ ਨੂੰ ਕਿਵੇਂ ਪਤਾ ਲੱਗਿਆ ਮੇਰੇ ਪਰਸ ਗੁਆਚਣ ਦਾ? ਇਸ ਤੋਂ ਪਹਿਲਾਂ ਕਿ ਉਹ ਕੁਝ ਹੋਰ ਸੋਚਦਾ ਬਜ਼ੁਰਗ ਬੋਲਿਆ, "ਮੈਂ ਤਾਂ ਬਥੇਰੀਆਂ ਅਵਾਜ਼ਾਂ ਮਾਰੀਆਂ ਤੁਹਾਨੂੰ ਪਰ ਤੁਸੀਂ ਸੁਣੀਆਂ ਨਹੀਂ। ਤੁਸੀਂ ਤੇਜ਼ੀ ਵਿੱਚ ਸੀ। ਮੈਂ ਤੁਹਾਡੀ ਅਮਾਨਤ ਸੰਭਾਲ ਲਈ। ਮੈਨੂੰ ਪਤਾ ਸੀ ਤੁਸੀਂ ਵਾਪਸ ਆਓਗੇ।" ਕੁਝ ਸਾਲ ਦੇ ਨੇੜੇ ਲੱਗਦੇ ਕਮਜ਼ੋਰ ਪਰ ਚਮਕਦੀਆਂ ਅੱਖਾਂ ਵਾਲੇ ਬਜ਼ੁਰਗ ਨੇ ਆਪਣੀ ਜੇਬ੍ਹ ਵਿੱਚੋਂ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਪਰਸ ਕੱਢਿਆ ਤੇ ਗੁਰਮੀਤ ਦੇ ਹਵਾਲੇ ਕਰ ਦਿੱਤਾ। ਪਰਸ ਵੇਖ ਕੇ ਉਸ ਦੀ ਜਾਨ ਵਿੱਚ ਜਾਨ ਆਈ। ਗੁਰਮੀਤ ਸਿੰਘ ਨੇ ਨਾ ਚਾਹੁੰਦਿਆਂ ਹੋਇਆਂ ਵੀ ਆਪਣਾ ਪਰਸ ਖੋਲ੍ਹ ਕੇ ਵੇਖਿਆ। ਪਰਸ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਸੀ। ਫਿਰ ਉਹ ਟਿਕਟਿਕੀ ਲਾ ਉਸ ਬਜ਼ੁਰਗ ਵੱਲ ਤੱਕਣ ਲੱਗਾ। ਖਸਤਾ ਹਾਲਤ ਦੇ ਰਿਕਸ਼ੇ ਤੇ ਸਧਾਰਨ ਜਿਹੇ ਕੱਪੜਿਆਂ ਵਿੱਚ ਬੈਠਾ ਉਹ ਬਜ਼ੁਰਗ ਉਸ ਨੂੰ ਅਸਧਾਰਨ ਜਾਪਿਆ। ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਉਸ ਪ੍ਰਤੀ ਅਥਾਹ ਸਤਿਕਾਰ ਪੈਦਾ ਹੋ ਗਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e2bb9e3f-c4a6-4971-b6c4-ee85cd0298ac', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟਾਂ ਨਾਲ ਉਸ ਦਾ ਪਰਸ ਫੁੱਲ ਕੇ ਗੁਬਾਰੇ ਵਾਂਗ ਹੋ ਗਿਆ ਸੀ। ਉਸ ਨੇ ਅੱਖੇ-ਸੁੱਖੇ ਪਰਸ ਪੈਂਟ ਦੀ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਪਾਇਆ, ਕਿੱਕ ਮਾਰੀ ਤੇ ਘਰ ਵੱਲ ਚੱਲ ਪਿਆ। ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਜਾ ਕੇ ਜਦ ਉਸ ਨੇ ਆਦਤ ਅਨੁਸਾਰ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਮਾਰਿਆ ਤਾਂ ਜੇਬ੍ਹ ਖਾਲੀ ਸੀ। ਉਸ ਨੂੰ ਅਚੰਭਾ ਲੱਗਿਆ, ਵਿਸ਼ਵਾਸ ਨਾ ਹੋਇਆ। ਫਿਰ ਜੇਬ੍ਹ ਉੱਤੇ ਹੱਥ ਮਾਰਿਆ ਪਰ ਪਰਸ ਨਹੀਂ ਸੀ। ਉਸ ਨੇ ਫਟਾ-ਫਟ ਮੋਟਰਸਾਈਕਲ ਰੋਕੀ, ਕਾਹਲੀ ਨਾਲ ਸਾਰੀਆਂ ਜੇਬ੍ਹਾਂ ਵੇਖੀਆਂ ਪਰ ਪਰਸ ਨਾ ਮਿਲਿਆ। ਖਿਆਲ ਆਇਆ ਕਿ ਰਾਹ ਵਿੱਚ ਤਾਂ ਨਹੀਂ ਡਿੱਗ ਗਿਆ? ਅਣਗਿਣਤ ਖਿਆਲ ਮਨ ਵਿੱਚ ਘੁੰਮਣ ਲੱਗੇ, "ਇਹ ਤਾਂ ਮੇਰੀ ਮਿਹਨਤ ਦੀ ਕਮਾਈ ਸੀ। ਇਹ ਕਿਵੇਂ ਗੁਆਚ ਸਕਦੀ ਹੈ?" ਇੱਕ ਪਾਸੇ ਪਰਸ ਗੁਆਚਣ ਦਾ ਦੁੱਖ ਤੇ ਦੂਜੇ ਪਾਸੇ ਪੈਸਿਆਂ ਦੀ ਉਡੀਕ ਵਿੱਚ ਬੈਠੇ ਕਾਮੇ ਉਸ ਦੀ ਚਿੰਤਾ ਵਧਾ ਰਹੇ ਸਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0e542fe9-b676-43ea-9717-a5e7ba0ea43f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲ ਵਿੱਚ ਇੱਕ ਆਸ ਸੀ ਕਿ ਸ਼ਾਇਦ ਕਿਸੇ ਨੂੰ ਲੱਭ ਗਿਆ ਹੋਵੇ ਤੇ ਉਹ ਵਾਪਸ ਕਰ ਦੇਵੇਗਾ। ਪਰ ਦੂਜੇ ਹੀ ਪਲ ਇਹ ਸੋਚ ਬਦਲ ਜਾਂਦੀ ਕਿ ਅੱਜ ਦੇ ਜ਼ਮਾਨੇ ਵਿੱਚ ਜਿੱਥੇ ਲੋਕ ਹੱਥੋਂ ਮੋਬਾਈਲ ਤੇ ਘਰੋਂ ਕੀਮਤੀ ਸਮਾਨ ਖੋਹ ਕੇ ਭੱਜ ਜਾਂਦੇ ਨੇ, ਫਿਰ ਕਿਸੇ ਨੇ ਵਾਪਸ ਕਰਨਾ ਮੇਰਾ ਪਰਸ। ਨਾਲੇ ਪੰਜ-ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟ ਕਿਸੇ ਦਾ ਵੀ ਈਮਾਨ ਡੁਲਾ ਸਕਦੇ ਨੇ। ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਫੇਰਦਿਆਂ-ਫੇਰਦਿਆਂ ਜਦ ਉਹ ਬੈਂਕ ਤੋਂ ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਸੀ ਤਾਂ ਕਿਸੇ ਨੇ ਅਵਾਜ਼ ਮਾਰੀ, "ਸਰਦਾਰ ਜੀ, ਪਰਸ ਗੁਆਚ ਗਿਆ ਹੈ?" ਗੁਰਮੀਤ ਹੈਰਾਨ ਹੋ ਗਿਆ। ਉਹ ਸੋਚੀਂ ਪੈ ਗਿਆ। ਇਹ ਬਜ਼ੁਰਗ ਕੌਣ ਨੇ? ਇਹਨਾਂ ਨੂੰ ਕਿਵੇਂ ਪਤਾ ਲੱਗਿਆ ਮੇਰੇ ਪਰਸ ਗੁਆਚਣ ਦਾ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
