  ('f7f351ca-c306-4aed-933e-bee8e3e3cc59', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟਾਂ ਨਾਲ ਉਸ ਦਾ ਪਰਸ ਫੁੱਲ ਕੇ ਗੁਬਾਰੇ ਵਾਂਗ ਹੋ ਗਿਆ ਸੀ। ਉਸ ਨੇ ਅੱਖੇ-ਸੁੱਖੇ ਪਰਸ ਪੈਂਟ ਦੀ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਪਾਇਆ, ਕਿੱਕ ਮਾਰੀ ਤੇ ਘਰ ਵੱਲ ਚੱਲ ਪਿਆ। ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਜਾ ਕੇ ਜਦ ਉਸ ਨੇ ਆਦਤ ਅਨੁਸਾਰ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਮਾਰਿਆ ਤਾਂ ਜੇਬ੍ਹ ਖਾਲੀ ਸੀ। ਉਸ ਨੂੰ ਅਚੰਭਾ ਲੱਗਿਆ, ਵਿਸ਼ਵਾਸ ਨਾ ਹੋਇਆ। ਫਿਰ ਜੇਬ੍ਹ ਉੱਤੇ ਹੱਥ ਮਾਰਿਆ ਪਰ ਪਰਸ ਨਹੀਂ ਸੀ। ਉਸ ਨੇ ਫਟਾ-ਫਟ ਮੋਟਰਸਾਈਕਲ ਰੋਕੀ, ਕਾਹਲੀ ਨਾਲ ਸਾਰੀਆਂ ਜੇਬ੍ਹਾਂ ਵੇਖੀਆਂ ਪਰ ਪਰਸ ਨਾ ਮਿਲਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('247eee2b-08ce-46e5-9fe2-d805c328a5df', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਖਿਆਲ ਆਇਆ ਕਿ ਰਾਹ ਵਿੱਚ ਤਾਂ ਨਹੀਂ ਡਿੱਗ ਗਿਆ? ਅਣਗਿਣਤ ਖਿਆਲ ਮਨ ਵਿੱਚ ਘੁੰਮਣ ਲੱਗੇ, "ਇਹ ਤਾਂ ਮੇਰੀ ਮਿਹਨਤ ਦੀ ਕਮਾਈ ਸੀ। ਇਹ ਕਿਵੇਂ ਗੁਆਚ ਸਕਦੀ ਹੈ?" ਇੱਕ ਪਾਸੇ ਪਰਸ ਗੁਆਚਣ ਦਾ ਦੁੱਖ ਤੇ ਦੂਜੇ ਪਾਸੇ ਪੈਸਿਆਂ ਦੀ ਉਡੀਕ ਵਿੱਚ ਬੈਠੇ ਕਾਮੇ ਉਸ ਦੀ ਚਿੰਤਾ ਵਧਾ ਰਹੇ ਸਨ। ਉਸ ਨੇ ਤੁਰੰਤ ਮੋਟਰਸਾਈਕਲ ਘੁਮਾਇਆ। ਦਿਲ ਵਿੱਚ ਇੱਕ ਆਸ ਸੀ ਕਿ ਸ਼ਾਇਦ ਕਿਸੇ ਨੂੰ ਲੱਭ ਗਿਆ ਹੋਵੇ ਤੇ ਉਹ ਵਾਪਸ ਕਰ ਦੇਵੇਗਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ca4953ee-5c15-4696-b027-3a88774cdf9e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰ ਦੂਜੇ ਹੀ ਪਲ ਇਹ ਸੋਚ ਬਦਲ ਜਾਂਦੀ ਕਿ ਅੱਜ ਦੇ ਜ਼ਮਾਨੇ ਵਿੱਚ ਜਿੱਥੇ ਲੋਕ ਹੱਥੋਂ ਮੋਬਾਈਲ ਤੇ ਘਰੋਂ ਕੀਮਤੀ ਸਮਾਨ ਖੋਹ ਕੇ ਭੱਜ ਜਾਂਦੇ ਨੇ, ਫਿਰ ਕਿਸੇ ਨੇ ਵਾਪਸ ਕਰਨਾ ਮੇਰਾ ਪਰਸ। ਨਾਲੇ ਪੰਜ-ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟ ਕਿਸੇ ਦਾ ਵੀ ਈਮਾਨ ਡੁਲਾ ਸਕਦੇ ਨੇ। ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਫੇਰਦਿਆਂ-ਫੇਰਦਿਆਂ ਜਦ ਉਹ ਬੈਂਕ ਤੋਂ ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਸੀ ਤਾਂ ਕਿਸੇ ਨੇ ਅਵਾਜ਼ ਮਾਰੀ, "ਸਰਦਾਰ ਜੀ, ਪਰਸ ਗੁਆਚ ਗਿਆ ਹੈ?"$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('dd8318e2-31fa-46fa-b710-7cd07e2d121a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਗੁਰਮੀਤ ਹੈਰਾਨ ਹੋ ਗਿਆ। ਉਹ ਸੋਚੀਂ ਪੈ ਗਿਆ। ਇਹ ਬਜ਼ੁਰਗ ਕੌਣ ਨੇ? ਇਹਨਾਂ ਨੂੰ ਕਿਵੇਂ ਪਤਾ ਲੱਗਿਆ ਮੇਰੇ ਪਰਸ ਗੁਆਚਣ ਦਾ? ਇਸ ਤੋਂ ਪਹਿਲਾਂ ਕਿ ਉਹ ਕੁਝ ਹੋਰ ਸੋਚਦਾ ਬਜ਼ੁਰਗ ਬੋਲਿਆ, "ਮੈਂ ਤਾਂ ਬਥੇਰੀਆਂ ਅਵਾਜ਼ਾਂ ਮਾਰੀਆਂ ਤੁਹਾਨੂੰ ਪਰ ਤੁਸੀਂ ਸੁਣੀਆਂ ਨਹੀਂ। ਤੁਸੀਂ ਤੇਜ਼ੀ ਵਿੱਚ ਸੀ। ਮੈਂ ਤੁਹਾਡੀ ਅਮਾਨਤ ਸੰਭਾਲ ਲਈ। ਮੈਨੂੰ ਪਤਾ ਸੀ ਤੁਸੀਂ ਵਾਪਸ ਆਓਗੇ।" ਕੁਝ ਸਾਲ ਦੇ ਨੇੜੇ ਲੱਗਦੇ ਕਮਜ਼ੋਰ ਪਰ ਚਮਕਦੀਆਂ ਅੱਖਾਂ ਵਾਲੇ ਬਜ਼ੁਰਗ ਨੇ ਆਪਣੀ ਜੇਬ੍ਹ ਵਿੱਚੋਂ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਪਰਸ ਕੱਢਿਆ ਤੇ ਗੁਰਮੀਤ ਦੇ ਹਵਾਲੇ ਕਰ ਦਿੱਤਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('679594ae-6744-4be5-b13b-45c753d5e907', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰਸ ਵੇਖ ਕੇ ਉਸ ਦੀ ਜਾਨ ਵਿੱਚ ਜਾਨ ਆਈ। ਗੁਰਮੀਤ ਸਿੰਘ ਨੇ ਨਾ ਚਾਹੁੰਦਿਆਂ ਹੋਇਆਂ ਵੀ ਆਪਣਾ ਪਰਸ ਖੋਲ੍ਹ ਕੇ ਵੇਖਿਆ। ਪਰਸ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਸੀ। ਫਿਰ ਉਹ ਟਿਕਟਿਕੀ ਲਾ ਉਸ ਬਜ਼ੁਰਗ ਵੱਲ ਤੱਕਣ ਲੱਗਾ। ਖਸਤਾ ਹਾਲਤ ਦੇ ਰਿਕਸ਼ੇ ਤੇ ਸਧਾਰਨ ਜਿਹੇ ਕੱਪੜਿਆਂ ਵਿੱਚ ਬੈਠਾ ਉਹ ਬਜ਼ੁਰਗ ਉਸ ਨੂੰ ਅਸਧਾਰਨ ਜਾਪਿਆ। ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਉਸ ਪ੍ਰਤੀ ਅਥਾਹ ਸਤਿਕਾਰ ਪੈਦਾ ਹੋ ਗਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('bf7e9b9a-eb98-48aa-9f50-8f8476d20d52', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟਾਂ ਨਾਲ ਉਸ ਦਾ ਪਰਸ ਫੁੱਲ ਕੇ ਗੁਬਾਰੇ ਵਾਂਗ ਹੋ ਗਿਆ ਸੀ। ਉਸ ਨੇ ਅੱਖੇ-ਸੁੱਖੇ ਪਰਸ ਪੈਂਟ ਦੀ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਪਾਇਆ, ਕਿੱਕ ਮਾਰੀ ਤੇ ਘਰ ਵੱਲ ਚੱਲ ਪਿਆ। ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਜਾ ਕੇ ਜਦ ਉਸ ਨੇ ਆਦਤ ਅਨੁਸਾਰ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਮਾਰਿਆ ਤਾਂ ਜੇਬ੍ਹ ਖਾਲੀ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f2e6a4a2-d31c-413f-994f-45a534d29649', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਨੂੰ ਅਚੰਭਾ ਲੱਗਿਆ, ਵਿਸ਼ਵਾਸ ਨਾ ਹੋਇਆ। ਫਿਰ ਜੇਬ੍ਹ ਉੱਤੇ ਹੱਥ ਮਾਰਿਆ ਪਰ ਪਰਸ ਨਹੀਂ ਸੀ। ਉਸ ਨੇ ਫਟਾ-ਫਟ ਮੋਟਰਸਾਈਕਲ ਰੋਕੀ, ਕਾਹਲੀ ਨਾਲ ਸਾਰੀਆਂ ਜੇਬ੍ਹਾਂ ਵੇਖੀਆਂ ਪਰ ਪਰਸ ਨਾ ਮਿਲਿਆ। ਖਿਆਲ ਆਇਆ ਕਿ ਰਾਹ ਵਿੱਚ ਤਾਂ ਨਹੀਂ ਡਿੱਗ ਗਿਆ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f0e5916b-760e-443b-b649-1a70e62723a7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਣਗਿਣਤ ਖਿਆਲ ਮਨ ਵਿੱਚ ਘੁੰਮਣ ਲੱਗੇ, "ਇਹ ਤਾਂ ਮੇਰੀ ਮਿਹਨਤ ਦੀ ਕਮਾਈ ਸੀ। ਇਹ ਕਿਵੇਂ ਗੁਆਚ ਸਕਦੀ ਹੈ?" ਇੱਕ ਪਾਸੇ ਪਰਸ ਗੁਆਚਣ ਦਾ ਦੁੱਖ ਤੇ ਦੂਜੇ ਪਾਸੇ ਪੈਸਿਆਂ ਦੀ ਉਡੀਕ ਵਿੱਚ ਬੈਠੇ ਕਾਮੇ ਉਸ ਦੀ ਚਿੰਤਾ ਵਧਾ ਰਹੇ ਸਨ। ਉਸ ਨੇ ਤੁਰੰਤ ਮੋਟਰਸਾਈਕਲ ਘੁਮਾਇਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a61cb0b9-1662-43e7-b25d-ea3914df355e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿਲ ਵਿੱਚ ਇੱਕ ਆਸ ਸੀ ਕਿ ਸ਼ਾਇਦ ਕਿਸੇ ਨੂੰ ਲੱਭ ਗਿਆ ਹੋਵੇ ਤੇ ਉਹ ਵਾਪਸ ਕਰ ਦੇਵੇਗਾ। ਪਰ ਦੂਜੇ ਹੀ ਪਲ ਇਹ ਸੋਚ ਬਦਲ ਜਾਂਦੀ ਕਿ ਅੱਜ ਦੇ ਜ਼ਮਾਨੇ ਵਿੱਚ ਜਿੱਥੇ ਲੋਕ ਹੱਥੋਂ ਮੋਬਾਈਲ ਤੇ ਘਰੋਂ ਕੀਮਤੀ ਸਮਾਨ ਖੋਹ ਕੇ ਭੱਜ ਜਾਂਦੇ ਨੇ, ਫਿਰ ਕਿਸੇ ਨੇ ਵਾਪਸ ਕਰਨਾ ਮੇਰਾ ਪਰਸ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('116cf7c4-81b9-4414-a2d1-f2828bb68d64', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਾਲੇ ਪੰਜ-ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟ ਕਿਸੇ ਦਾ ਵੀ ਈਮਾਨ ਡੁਲਾ ਸਕਦੇ ਨੇ। ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਫੇਰਦਿਆਂ-ਫੇਰਦਿਆਂ ਜਦ ਉਹ ਬੈਂਕ ਤੋਂ ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਸੀ ਤਾਂ ਕਿਸੇ ਨੇ ਅਵਾਜ਼ ਮਾਰੀ, "ਸਰਦਾਰ ਜੀ, ਪਰਸ ਗੁਆਚ ਗਿਆ ਹੈ?" ਗੁਰਮੀਤ ਹੈਰਾਨ ਹੋ ਗਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ab5442e7-2497-4fcb-aa6e-43d5349729ef', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹ ਸੋਚੀਂ ਪੈ ਗਿਆ। ਇਹ ਬਜ਼ੁਰਗ ਕੌਣ ਨੇ? ਇਹਨਾਂ ਨੂੰ ਕਿਵੇਂ ਪਤਾ ਲੱਗਿਆ ਮੇਰੇ ਪਰਸ ਗੁਆਚਣ ਦਾ? ਇਸ ਤੋਂ ਪਹਿਲਾਂ ਕਿ ਉਹ ਕੁਝ ਹੋਰ ਸੋਚਦਾ ਬਜ਼ੁਰਗ ਬੋਲਿਆ, "ਮੈਂ ਤਾਂ ਬਥੇਰੀਆਂ ਅਵਾਜ਼ਾਂ ਮਾਰੀਆਂ ਤੁਹਾਨੂੰ ਪਰ ਤੁਸੀਂ ਸੁਣੀਆਂ ਨਹੀਂ। ਤੁਸੀਂ ਤੇਜ਼ੀ ਵਿੱਚ ਸੀ। ਮੈਂ ਤੁਹਾਡੀ ਅਮਾਨਤ ਸੰਭਾਲ ਲਈ। ਮੈਨੂੰ ਪਤਾ ਸੀ ਤੁਸੀਂ ਵਾਪਸ ਆਓਗੇ।"$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('075bea2f-bdc2-47d0-94fa-07ffaf218fe1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਝ ਸਾਲ ਦੇ ਨੇੜੇ ਲੱਗਦੇ ਕਮਜ਼ੋਰ ਪਰ ਚਮਕਦੀਆਂ ਅੱਖਾਂ ਵਾਲੇ ਬਜ਼ੁਰਗ ਨੇ ਆਪਣੀ ਜੇਬ੍ਹ ਵਿੱਚੋਂ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਪਰਸ ਕੱਢਿਆ ਤੇ ਗੁਰਮੀਤ ਦੇ ਹਵਾਲੇ ਕਰ ਦਿੱਤਾ। ਪਰਸ ਵੇਖ ਕੇ ਉਸ ਦੀ ਜਾਨ ਵਿੱਚ ਜਾਨ ਆਈ। ਗੁਰਮੀਤ ਸਿੰਘ ਨੇ ਨਾ ਚਾਹੁੰਦਿਆਂ ਹੋਇਆਂ ਵੀ ਆਪਣਾ ਪਰਸ ਖੋਲ੍ਹ ਕੇ ਵੇਖਿਆ। ਪਰਸ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('83efb795-f1c5-4348-bd91-5a703ecf9d18', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਿਰ ਉਹ ਟਿਕਟਿਕੀ ਲਾ ਉਸ ਬਜ਼ੁਰਗ ਵੱਲ ਤੱਕਣ ਲੱਗਾ। ਖਸਤਾ ਹਾਲਤ ਦੇ ਰਿਕਸ਼ੇ ਤੇ ਸਧਾਰਨ ਜਿਹੇ ਕੱਪੜਿਆਂ ਵਿੱਚ ਬੈਠਾ ਉਹ ਬਜ਼ੁਰਗ ਉਸ ਨੂੰ ਅਸਧਾਰਨ ਜਾਪਿਆ। ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਉਸ ਪ੍ਰਤੀ ਅਥਾਹ ਸਤਿਕਾਰ ਪੈਦਾ ਹੋ ਗਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('eda06ec1-8800-4f5c-90b9-f872301be76c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟਾਂ ਨਾਲ ਉਸ ਦਾ ਪਰਸ ਫੁੱਲ ਕੇ ਗੁਬਾਰੇ ਵਾਂਗ ਹੋ ਗਿਆ ਸੀ। ਉਸ ਨੇ ਅੱਖੇ-ਸੁੱਖੇ ਪਰਸ ਪੈਂਟ ਦੀ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਪਾਇਆ, ਕਿੱਕ ਮਾਰੀ ਤੇ ਘਰ ਵੱਲ ਚੱਲ ਪਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('85c54512-f1b3-4a4c-8dd5-191cc2b67203', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਨੂੰ ਅਚੰਭਾ ਲੱਗਿਆ, ਵਿਸ਼ਵਾਸ ਨਾ ਹੋਇਆ। ਫਿਰ ਜੇਬ੍ਹ ਉੱਤੇ ਹੱਥ ਮਾਰਿਆ ਪਰ ਪਰਸ ਨਹੀਂ ਸੀ। ਉਸ ਨੇ ਫਟਾ-ਫਟ ਮੋਟਰਸਾਈਕਲ ਰੋਕੀ, ਕਾਹਲੀ ਨਾਲ ਸਾਰੀਆਂ ਜੇਬ੍ਹਾਂ ਵੇਖੀਆਂ ਪਰ ਪਰਸ ਨਾ ਮਿਲਿਆ। ਖਿਆਲ ਆਇਆ ਕਿ ਰਾਹ ਵਿੱਚ ਤਾਂ ਨਹੀਂ ਡਿੱਗ ਗਿਆ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b2ce522d-1991-4524-82aa-f04ede5add9a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਣਗਿਣਤ ਖਿਆਲ ਮਨ ਵਿੱਚ ਘੁੰਮਣ ਲੱਗੇ, "ਇਹ ਤਾਂ ਮੇਰੀ ਮਿਹਨਤ ਦੀ ਕਮਾਈ ਸੀ। ਇਹ ਕਿਵੇਂ ਗੁਆਚ ਸਕਦੀ ਹੈ?" ਇੱਕ ਪਾਸੇ ਪਰਸ ਗੁਆਚਣ ਦਾ ਦੁੱਖ ਤੇ ਦੂਜੇ ਪਾਸੇ ਪੈਸਿਆਂ ਦੀ ਉਡੀਕ ਵਿੱਚ ਬੈਠੇ ਕਾਮੇ ਉਸ ਦੀ ਚਿੰਤਾ ਵਧਾ ਰਹੇ ਸਨ। ਉਸ ਨੇ ਤੁਰੰਤ ਮੋਟਰਸਾਈਕਲ ਘੁਮਾਇਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
