  ('89181859-b174-4027-92d2-b7c46688c121', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹ ਸੋਚੀਂ ਪੈ ਗਿਆ। ਇਹ ਬਜ਼ੁਰਗ ਕੌਣ ਨੇ? ਇਹਨਾਂ ਨੂੰ ਕਿਵੇਂ ਪਤਾ ਲੱਗਿਆ ਮੇਰੇ ਪਰਸ ਗੁਆਚਣ ਦਾ? ਇਸ ਤੋਂ ਪਹਿਲਾਂ ਕਿ ਉਹ ਕੁਝ ਹੋਰ ਸੋਚਦਾ ਬਜ਼ੁਰਗ ਬੋਲਿਆ, "ਮੈਂ ਤਾਂ ਬਥੇਰੀਆਂ ਅਵਾਜ਼ਾਂ ਮਾਰੀਆਂ ਤੁਹਾਨੂੰ ਪਰ ਤੁਸੀਂ ਸੁਣੀਆਂ ਨਹੀਂ। ਤੁਸੀਂ ਤੇਜ਼ੀ ਵਿੱਚ ਸੀ। ਮੈਂ ਤੁਹਾਡੀ ਅਮਾਨਤ ਸੰਭਾਲ ਲਈ। ਮੈਨੂੰ ਪਤਾ ਸੀ ਤੁਸੀਂ ਵਾਪਸ ਆਓਗੇ।"$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8250168d-4228-4f5e-8e24-7f4fa0c0db54', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਝ ਸਾਲ ਦੇ ਨੇੜੇ ਲੱਗਦੇ ਕਮਜ਼ੋਰ ਪਰ ਚਮਕਦੀਆਂ ਅੱਖਾਂ ਵਾਲੇ ਬਜ਼ੁਰਗ ਨੇ ਆਪਣੀ ਜੇਬ੍ਹ ਵਿੱਚੋਂ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਪਰਸ ਕੱਢਿਆ ਤੇ ਗੁਰਮੀਤ ਦੇ ਹਵਾਲੇ ਕਰ ਦਿੱਤਾ। ਪਰਸ ਵੇਖ ਕੇ ਉਸ ਦੀ ਜਾਨ ਵਿੱਚ ਜਾਨ ਆਈ। ਗੁਰਮੀਤ ਸਿੰਘ ਨੇ ਨਾ ਚਾਹੁੰਦਿਆਂ ਹੋਇਆਂ ਵੀ ਆਪਣਾ ਪਰਸ ਖੋਲ੍ਹ ਕੇ ਵੇਖਿਆ। ਪਰਸ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('fbda2294-a022-4219-a0d8-2b5a93646ec9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਿਰ ਉਹ ਟਿਕਟਿਕੀ ਲਾ ਉਸ ਬਜ਼ੁਰਗ ਵੱਲ ਤੱਕਣ ਲੱਗਾ। ਖਸਤਾ ਹਾਲਤ ਦੇ ਰਿਕਸ਼ੇ ਤੇ ਸਧਾਰਨ ਜਿਹੇ ਕੱਪੜਿਆਂ ਵਿੱਚ ਬੈਠਾ ਉਹ ਬਜ਼ੁਰਗ ਉਸ ਨੂੰ ਅਸਧਾਰਨ ਜਾਪਿਆ। ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਉਸ ਪ੍ਰਤੀ ਅਥਾਹ ਸਤਿਕਾਰ ਪੈਦਾ ਹੋ ਗਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2998e1fd-8112-4c45-9644-06e18bc74257', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜ ਸੌ ਦੇ ਨਵੇਂ-ਨਕੋਰ ਨੋਟਾਂ ਨਾਲ ਉਸ ਦਾ ਪਰਸ ਫੁੱਲ ਕੇ ਗੁਬਾਰੇ ਵਾਂਗ ਹੋ ਗਿਆ ਸੀ। ਉਸ ਨੇ ਅੱਖੇ-ਸੁੱਖੇ ਪਰਸ ਪੈਂਟ ਦੀ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਪਾਇਆ, ਕਿੱਕ ਮਾਰੀ ਤੇ ਘਰ ਵੱਲ ਚੱਲ ਪਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('4008687d-824b-419e-98c2-876eb880d8ff', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਝ ਦੂਰੀ ਉੱਤੇ ਜਾ ਕੇ ਜਦ ਉਸ ਨੇ ਆਦਤ ਅਨੁਸਾਰ ਪਿਛਲੀ ਜੇਬ੍ਹ ਵਿੱਚ ਹੱਥ ਮਾਰਿਆ ਤਾਂ ਜੇਬ੍ਹ ਖਾਲੀ ਸੀ। ਉਸ ਨੂੰ ਅਚੰਭਾ ਲੱਗਿਆ, ਵਿਸ਼ਵਾਸ ਨਾ ਹੋਇਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('bbb9a55d-4d74-418d-af08-00f18156962b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੱਕ ਪਾਸੇ ਪਰਸ ਗੁਆਚਣ ਦਾ ਦੁੱਖ ਤੇ ਦੂਜੇ ਪਾਸੇ ਪੈਸਿਆਂ ਦੀ ਉਡੀਕ ਵਿੱਚ ਬੈਠੇ ਕਾਮੇ ਉਸ ਦੀ ਚਿੰਤਾ ਵਧਾ ਰਹੇ ਸਨ। ਉਸ ਨੇ ਤੁਰੰਤ ਮੋਟਰਸਾਈਕਲ ਘੁਮਾਇਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('b0f46d46-6448-4301-995c-4cc71aede582', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰ ਦੂਜੇ ਹੀ ਪਲ ਇਹ ਸੋਚ ਬਦਲ ਜਾਂਦੀ ਕਿ ਅੱਜ ਦੇ ਜ਼ਮਾਨੇ ਵਿੱਚ ਜਿੱਥੇ ਲੋਕ ਹੱਥੋਂ ਮੋਬਾਈਲ ਤੇ ਘਰੋਂ ਕੀਮਤੀ ਸਮਾਨ ਖੋਹ ਕੇ ਭੱਜ ਜਾਂਦੇ ਨੇ, ਫਿਰ ਕਿਸੇ ਨੇ ਵਾਪਸ ਕਰਨਾ ਮੇਰਾ ਪਰਸ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('e75f3881-fbbf-41f6-b8d5-16cfb74cbe11', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬਜ਼ੁਰਗ ਬੋਲਿਆ, "ਮੈਂ ਤਾਂ ਬਥੇਰੀਆਂ ਅਵਾਜ਼ਾਂ ਮਾਰੀਆਂ ਤੁਹਾਨੂੰ ਪਰ ਤੁਸੀਂ ਸੁਣੀਆਂ ਨਹੀਂ। ਤੁਸੀਂ ਤੇਜ਼ੀ ਵਿੱਚ ਸੀ। ਮੈਂ ਤੁਹਾਡੀ ਅਮਾਨਤ ਸੰਭਾਲ ਲਈ। ਮੈਨੂੰ ਪਤਾ ਸੀ ਤੁਸੀਂ ਵਾਪਸ ਆਓਗੇ।"$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
