  ('a1af0ce3-9a08-4ad8-8951-c4f4c3e28e86', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰਸ ਵੇਖ ਕੇ ਉਸ ਦੀ ਜਾਨ ਵਿੱਚ ਜਾਨ ਆਈ। ਗੁਰਮੀਤ ਸਿੰਘ ਨੇ ਨਾ ਚਾਹੁੰਦਿਆਂ ਹੋਇਆਂ ਵੀ ਆਪਣਾ ਪਰਸ ਖੋਲ੍ਹ ਕੇ ਵੇਖਿਆ। ਪਰਸ ਨੋਟਾਂ ਨਾਲ ਭਰਿਆ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('2b8e0b9b-984f-4001-a0ba-adcb1d0fe0ba', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਖਸਤਾ ਹਾਲਤ ਦੇ ਰਿਕਸ਼ੇ ਤੇ ਸਧਾਰਨ ਜਿਹੇ ਕੱਪੜਿਆਂ ਵਿੱਚ ਬੈਠਾ ਉਹ ਬਜ਼ੁਰਗ ਉਸ ਨੂੰ ਅਸਧਾਰਨ ਜਾਪਿਆ। ਉਸ ਦੇ ਮਨ ਵਿੱਚ ਉਸ ਪ੍ਰਤੀ ਅਥਾਹ ਸਤਿਕਾਰ ਪੈਦਾ ਹੋ ਗਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('8cd53a64-b9c1-4f0d-b076-9059cb65243f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸੋਚ ਰਿਹਾ ਸੀ ਕਿ ਹਰ ਰੋਜ਼ ਤਿੰਨ ਤੋਂ ਚਾਰ ਸੌ ਰੁਪਏ ਕਮਾਉਣ ਵਾਲੇ ਦੇ ਮਨ ਵਿੱਚ ਇਸ ਪਰਸ ਨੂੰ ਰੱਖਣ ਦਾ ਲਾਲਚ ਕਿਉਂ ਨਾ ਆਇਆ? ਇਹਨਾਂ ਪੈਸਿਆਂ ਨਾਲ ਉਸ ਦਾ ਸਾਲ ਭਰ ਦਾ ਖਰਚਾ ਬਣੇ ਲੱਗ ਜਾਣਾ ਸੀ। ਉਸ ਅੰਦਰ ਐਸਾ ਕੀ ਹੈ ਜੋ ਆਮ ਲੋਕਾਂ ਵਿੱਚ ਨਹੀਂ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b2cc255b-ed8e-494e-b8db-a622e5694392', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਨੇ ਪੰਜ-ਪੰਜ ਸੌ ਦੇ ਦੋ ਨੋਟ ਰਿਕਸ਼ੇ ਵਾਲੇ ਵੱਲ ਵਧਾ ਕੇ ਬੜੇ ਸਤਿਕਾਰ ਨਾਲ ਕਿਹਾ, ÒÒਤੁਹਾਡਾ ਇਨਾਮ ਬਜ਼ੁਰਗੋ।ÓÓ ÒÒਤੁਹਾਡਾ ਦਿਲੋਂ ਸ਼ੁਕਰਾਨਾ।ÓÓ ਬਜ਼ੁਰਗ ਰਿਕਸ਼ੇ ਵਾਲੇ ਨੇ ਥੋੜ੍ਹਾ ਮੁਸਕੁਰਾ ਕੇ ਬੜੇ ਅਦਬ ਨਾਲ ਕਿਹਾ, ÒÒਨਹੀਂ ਸਰਦਾਰ ਸਾਹਿਬ, ਇਹ ਪੈਸੇ ਮੈਂ ਨਹੀਂ ਲੈਣੇ। ਇਹਨਾਂ ਉੱਤੇ ਮੇਰਾ ਕੋਈ ਹੱਕ ਨਹੀਂ। ਇਹ ਤੁਹਾਡੀ ਦਸਾਂ-ਨਹੁੰਆਂ ਦੀ ਕਿਰਤ ਹੈ।ÓÓ$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c5e9f1a6-6425-4255-bead-98ee294408a8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਗੁਰਮੀਤ ਸਿੰਘ ਮੁਸਕੁਰਾ ਕੇ ਕਹਿਣ ਲੱਗਾ, ÒÒਇਹ ਤੁਹਾਡੀ ਇਮਾਨਦਾਰੀ ਦਾ ਇਨਾਮ ਹੈ ਬਾਬਾ ਜੀ।ÓÓ ÒÒਨਹੀਂ ਸਰਦਾਰ ਸਾਹਿਬ, ਮੈਂ ਕਿਸੇ ਦੀ ਕਿਰਤ-ਕਮਾਈ ਨਹੀਂ ਲੈ ਸਕਦਾ। ਤੁਹਾਡਾ ਪਰਸ ਵਾਪਸ ਕਰਕੇ ਤਾਂ ਮੈਂ ਆਪਣਾ ਫਰਜ਼ ਨਿਭਾਇਆ ਹੈ।ÓÓ$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5f1b8bb5-f9a8-4782-8d59-ea420dab27c2', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਗੱਲ ਸੁਣਦਿਆਂ ਹੀ ਗੁਰਮੀਤ ਸਿੰਘ ਦੀਆਂ ਅੱਖਾਂ ਨਮ ਹੋ ਗਈਆਂ। ਘੋਰ ਗਰੀਬੀ ਦਾ ਸਾਹਮਣਾ ਕਰ ਰਿਹਾ ਇਹ ਰਿਕਸ਼ਾ ਚਾਲਕ ਉਸ ਨੂੰ ਕਿਸੇ ਦਾਤੇ ਤੋਂ ਘੱਟ ਨਹੀਂ ਲੱਗ ਰਿਹਾ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c3b181a7-4681-4980-a5e6-9e472f3c0b8e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਗੁਰਮੀਤ ਨੂੰ ਸੋਚਾਂ ਵਿੱਚ ਗੁਆਚਿਆ ਵੇਖ ਰਿਕਸ਼ਾ ਵਾਲਾ ਬੋਲਿਆ, ÒÒਕੀ ਹੋ ਗਿਆ ਸਰਦਾਰ ਜੀ? ਕੀ ਸੋਚਣ ਲੱਗ ਪਏ?ÓÓ ÒÒਕੁਝ ਨਹੀਂ... ਕੁਝ ਨਹੀਂ, ਬੱਸ ਐਵੇਂ ਹੀ। ਤੁਹਾਡਾ ਨਾਂ ਕੀ ਹੈ ਬਾਬਾ ਜੀ? ਤੁਸੀਂ ਕਿੱਥੇ ਰਹਿੰਦੇ ਹੋ?ÓÓ ਗੁਰਮੀਤ ਸਿੰਘ ਬੋਲਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f1d2c87e-ce62-4cea-aac9-4803af5c69a7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ÒÒਰਹਿਮਤ ਸਿੰਘ ਐ ਮੇਰਾ ਨਾਂ ਸਰਦਾਰ ਸਾਹਿਬ,ÓÓ ਬਜ਼ੁਰਗ ਨੇ ਨਿਮਰਤਾ ਨਾਲ ਜਵਾਬ ਦਿੱਤਾ। ਉਸ ਦਾ ਨਾਂ ਸੁਣ ਕੇ ਗੁਰਮੀਤ ਨੂੰ ਇੰਝ ਲੱਗਿਆ ਕਿ ਮਹੀਨੇ ਵਿੱਚ ਦੋ-ਤਿੰਨ ਹਜ਼ਾਰ ਰੁਪਏ ਕਮਾਉਣ ਵਾਲੇ ਰਹਿਮਤ ਸਿੰਘ ਉੱਤੇ ਸੱਚ-ਮੁੱਚ ਖੁਦਾ ਦੀ ਰਹਿਮਤ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0f3d2c5e-43c6-4adc-bd71-6a56b02401e1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਰਹਿਮਤ ਸਿੰਘ ਦੀ ਖੁਦਦਾਰੀ, ਇਮਾਨਦਾਰੀ ਅਤੇ ਚੜ੍ਹਦੀ ਕਲਾ ਵਿੱਚ ਰਹਿਣ ਦਾ ਸਰੂਰ ਗੁਰਮੀਤ ਸਿੰਘ ਦੇ ਚੇਤੇ ਵਿੱਚ ਵੱਸ ਗਿਆ। ਉਸ ਦਿਨ ਤੋਂ ਗੁਰਮੀਤ ਸਿੰਘ ਦੀ ਸੋਚ ਬਦਲ ਗਈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('917b865f-c35b-4862-b14e-851bbc281096', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਜੋਕੀ ਦੁਨੀਆ ਵਿੱਚ ਵੱਧ ਰਹੇ ਲਾਲਚ ਅਤੇ ਚੋਰੀ-ਠੱਗੀ ਦੀਆਂ ਘਟਨਾਵਾਂ ਵਿਚਕਾਰ ਵੀ ਰਹਿਮਤ ਸਿੰਘ ਵਰਗਾ ਬੰਦਾ ਬਾਕੀ ਹੈ। ਅੱਜ ਵੀ ਜਦੋਂ ਕਦੇ ਗੁਰਮੀਤ ਸਿੰਘ ਦਾ ਕੋਈ ਛੋਟਾ-ਮੋਟਾ ਨੁਕਸਾਨ ਹੋ ਜਾਂਦਾ ਜਾਂ ਕਿਸੇ ਦੀ ਕੀਤੀ ਚਲਾਕੀ ਜਾਂ ਠੱਗੀ ਸਾਹਮਣੇ ਆਉਂਦੀ ਤਾਂ ਉਹ ਅੱਖਾਂ ਬੰਦ ਕਰਕੇ ਰਹਿਮਤ ਸਿੰਘ ਨੂੰ ਯਾਦ ਕਰ ਲੈਂਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9da545bc-83aa-4e7f-936a-91bfd3e0161c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਹ ਸੋਚਦਾ ਹੈ ਕਿ ਸੱਚ, ਇਮਾਨਦਾਰੀ ਅਤੇ ਖੁਦਦਾਰੀ ਕਿਸੇ ਵੱਡੇ ਰੁਤਬੇ ਜਾਂ ਮਣਾਂ-ਮੂੰਹੀਂ ਦੌਲਤ ਨਾਲ ਨਹੀਂ, ਸਗੋਂ ਚੰਗੇ ਸੰਸਕਾਰ, ਸਬਰ ਅਤੇ ਰੱਬੀ ਰਹਿਮਤ ਨਾਲ ਹੀ ਮਿਲਦੇ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9958a43d-3d2e-497d-aad1-5e615862eba4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲਾਲਚ - ਲੋਭ, ਫਰਜ਼ ਨਿਭਾਉਣਾ - ਆਪਣੀ ਜ਼ਿੰਮੇਵਾਰੀ ਪੂਰੀ ਕਰਨਾ, ਨਿਮਰਤਾ - ਹਲੀਮੀ, ਖੁਦਦਾਰੀ - ਸਵੈ-ਸਨਮਾਨ, ਚੜ੍ਹਦੀ ਕਲਾ - ਉੱਚੇ ਮਨੋਬਲ ਵਿੱਚ ਰਹਿਣਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b43ff414-1055-429b-9ed1-2b66e94017ce', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '59170e6c-cb89-4ccd-851d-2c5e19341a56', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੂਜਿਆਂ ਪ੍ਰਤੀ ਇਮਾਨਦਾਰੀ ਦਿਖਾਉਣ ਦੀ ਭਾਵਨਾ ਦਾ ਵਿਕਾਸ। ਸੰਤੁਸ਼ਟੀ ਨਾਲ ਜੀਵਨ ਜਿਊਣ ਦੀ ਪ੍ਰੇਰਨਾ ਪੈਦਾ ਹੋਈ। ਸਿੱਖਣ ਨਤੀਜੇ (Learning Outcomes)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-005Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL);
